create extension if not exists pgcrypto;
create type public.user_role as enum ('customer','admin');
create type public.order_status as enum ('pending_payment','processing','revision','completed','rejected');
create type public.payment_status as enum ('unpaid','pending','paid','failed','expired');
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,role public.user_role not null default 'customer',created_at timestamptz default now());
create table if not exists public.services(id text primary key,name text not null,category text not null,price bigint not null,description text,active boolean default true,sort_order int default 0,updated_at timestamptz default now());
create table if not exists public.vouchers(id uuid primary key default gen_random_uuid(),code text unique not null,discount_pct numeric(5,2) not null,active boolean default true,expires_at timestamptz,created_at timestamptz default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,order_no text unique not null,title text not null,notes text,selected_services jsonb default '[]',priority boolean default false,subtotal bigint default 0,bundle_discount bigint default 0,voucher_discount bigint default 0,priority_fee bigint default 0,total bigint default 0,status public.order_status default 'pending_payment',payment_status public.payment_status default 'unpaid',payment_provider text,payment_reference text,payment_url text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.order_files(id uuid primary key default gen_random_uuid(),order_id uuid references public.orders(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,name text not null,path text not null,size bigint,created_at timestamptz default now());
create table if not exists public.revisions(id uuid primary key default gen_random_uuid(),order_id uuid references public.orders(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,message text not null,status text default 'open',created_at timestamptz default now());
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,order_id uuid references public.orders(id) on delete cascade,title text not null,body text not null,read_at timestamptz,created_at timestamptz default now());
insert into services(id,name,category,price,description,sort_order) values('bab1','Pendampingan Bab 1','BAB',175000,'Latar belakang, rumusan masalah, tujuan dan struktur penelitian.',1),('bab2','Pendampingan Bab 2','BAB',225000,'Landasan teori, penelitian terdahulu, kerangka dan hipotesis.',2),('bab3','Pendampingan Bab 3','BAB',250000,'Metode, populasi, sampel, variabel dan teknik analisis.',3),('bab4','Pendampingan Bab 4','BAB',350000,'Hasil penelitian, output, interpretasi dan pembahasan.',4),('bab5','Pendampingan Bab 5','BAB',150000,'Kesimpulan, implikasi, keterbatasan dan saran.',5),('olah','Analisis Data','DATA',275000,'Pendampingan SPSS/Excel dan interpretasi hasil.',6),('editing','Editing Akademik','EXTRA',125000,'Bahasa, struktur, konsistensi dan typo.',7),('format','Formatting Akhir','EXTRA',100000,'Daftar isi, tabel, gambar dan format kampus.',8) on conflict(id) do nothing;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,phone) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),coalesce(new.raw_user_meta_data->>'phone','')); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;

alter table profiles enable row level security;alter table services enable row level security;alter table vouchers enable row level security;alter table orders enable row level security;alter table order_files enable row level security;alter table revisions enable row level security;alter table notifications enable row level security;
create policy profiles_own on profiles for select using(auth.uid()=id);create policy services_read on services for select using(active=true);create policy orders_own on orders for select using(auth.uid()=user_id);create policy orders_insert on orders for insert with check(auth.uid()=user_id);create policy files_own on order_files for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy revisions_own on revisions for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy notifications_own on notifications for select using(auth.uid()=user_id);
create policy admin_orders on orders for all using(is_admin()) with check(is_admin());create policy admin_services on services for all using(is_admin()) with check(is_admin());create policy admin_vouchers on vouchers for all using(is_admin()) with check(is_admin());create policy admin_profiles on profiles for select using(is_admin());create policy admin_revisions on revisions for all using(is_admin()) with check(is_admin());create policy admin_notifications on notifications for all using(is_admin()) with check(is_admin());
insert into storage.buckets(id,name,public) values('order-files','order-files',false) on conflict(id) do nothing;
create policy order_files_read on storage.objects for select to authenticated using(bucket_id='order-files' and (storage.foldername(name))[1]=auth.uid()::text);create policy order_files_write on storage.objects for insert to authenticated with check(bucket_id='order-files' and (storage.foldername(name))[1]=auth.uid()::text);
